\section{Preliminaries}\label{ap:preliminaries}
\subsection{Choi--Jamio\l{}kowski isomorphism}
The Choi--Jamio\l{}kowski isomorphism~\cite{CHOI1975285, JAMIOLKOWSKI1972275} is a convenient way to represent quantum channels and superchannels. Given a quantum channel $\Phi: \mathcal{L}(\mathcal{I}) \to \mathcal{L}(\mathcal{O})$, its Choi matrix is defined by 
\begin{align}
  J_\Phi:=\sum_{i,j=1}^{d_{\mathcal{I}}} \ketbra{i}{j}_{\mathcal{I}} \otimes \Phi(\ketbra{i}{j})_{\mathcal{O}} \in \mathcal{L}(\mathcal{I} \otimes \mathcal{O}), 
\end{align}
satisfying the condition $J_\Phi \geq 0, \Tr_\mathcal{O}(J_\Phi) = \mathbb{I}_\mathcal{I}$. Under the Choi--Jamio\l{}kowski isomorphism, the composition of quantum channels $\Phi_1: \mathcal{L}(\mathcal{X}) \to \mathcal{L}(\mathcal{Y})$ and $\Phi_2: \mathcal{L}(\mathcal{Y}) \to \mathcal{L}(\mathcal{Z})$ is represented by the link product~\cite{chiribella2008quantum} defined by
\begin{align}
  J_{\Phi_2 \circ \Phi_1} = J_{\Phi_2} \star J_{\Phi_1} \coloneqq \Tr_{\mathcal{Y}}\left[
    (\mathbb{I}_{\mathcal{X}} \otimes J_{\Phi_2}) (J_{\Phi_1}^{\mathsf{T}_{\mathcal{Y}}} \otimes \mathbb{I}_{\mathcal{Z}})\right],
\end{align}
where $\star$ denotes the link product and $(\cdot)^{\mathsf{T}_{\mathcal{Y}}}$ denotes the partial transpose with respect to the subsystem $\mathcal{Y}$. Analogously, the Choi matrix of a sequential superchannel $\Xi$ is defined by
\begin{align}
    \mathcal{J}_\Xi  \coloneqq \mathcal{J}_{\Lambda_{n}} \star \mathcal{J}_{\Lambda_{n-1}} \star \cdots \mathcal{J}_{\Lambda_0}, 
\end{align}
where $\Lambda_i$ represent quantum channels appearing in the decomposition, Eq.~\eqref{eq:Seqdecomp}. The Choi matrix of the output channel $\Phi_{\textrm{out}} = \Xi(\Phi_1, \Phi_2 \cdots \Phi_n)$ is then given by 
\begin{align}
    \mathcal{J}_{\Phi_\textrm{out}} = \mathcal{J}_\Xi \star \qty[\bigotimes_{i=1}^n \mathcal{J}_{\Phi_i}]. 
\end{align}
The Choi matrix of a sequential superchannel $\Xi$ is fully characterized by the conditions~\cite{Chiribella_2008,chiribella2008quantum,chiribella2009theoretical}
\begin{align}\label{eq:seqChoi}
\begin{dcases}
\mathcal{J}_\Xi \geq 0 \\
\Tr_{I_k, O_k, \cdots I_{n+1}} (\mathcal{J}_\Xi) = \Tr_{O_{k-1}, I_k, O_k, \cdots I_{n+1}} (\mathcal{J}_\Xi)  \otimes \frac{\mathbb{I}_{O_{k-1}}}{d_{O_{k-1}}}\\
\Tr(\mathcal{J}_\Xi) = d_Pd_\mathbf{O}. 
\end{dcases}
\end{align}
for all $k\in[n+1]$ where $\mathbf{O}\coloneqq \bigotimes_{i=1}^{n} O_i$ and $d_X$ represents the dimension of a Hilbert space $X$. For parallel superchannels, this condition reduces to: 
\begin{align}\label{eq:parChoi}
\begin{dcases}
\mathcal{J}_\Xi \geq 0 \\
\tr_F(\mathcal{J}_\Xi) = \tr_{\mathbf{O}F}(\mathcal{J}_\Xi) \otimes \frac{\mathbb{I}_\mathbf{O}}{d_{\mathbf{O}}} \\
\tr_{\mathbf{I}\mathbf{O}F}(\mathcal{J}_\Xi) = \tr_{P\mathbf{I}\mathbf{O}F}(\mathcal{J}_\Xi)\otimes \frac{\mathbb{I}_P}{d_{P}} \\
\Tr(\mathcal{J}_\Xi) = d_Pd_{\mathbf{O}}, 
\end{dcases}
\end{align}
where $\mathbf{I}\coloneqq \bigotimes_{i=1}^{n} I_i$.

\subsection{Schur-Weyl duality}
Consider the following representation of the unitary group $U(d)$ and the symmetric group $\mathfrak{S}_n$,  
\begin{align}
    U^{\otimes n}|i_1\rangle \otimes  \cdots \otimes |i_n\rangle &= U|i_1\rangle \otimes \cdots \otimes U|i_n\rangle\\ \label{eq:perm}
    \pi(\sigma) |i_1\rangle \otimes  \cdots \otimes |i_n\rangle &= |i_{\sigma^{-1}(1)} \rangle \otimes \cdots \otimes |i_{\sigma^{-1}(n)} \rangle, 
\end{align}
for $U \in U(d)$ and $\sigma \in \mathfrak{S}_n$. The Schur-Weyl duality~\cite{ceccherini2010representation} is the following decomposition of the Hilbert space: 
\begin{align}
    (\mathbb{C}^{d})^{\otimes n} &\simeq \bigoplus_{\lambda \vdash_d n} \mathcal{U}_\lambda \otimes \mathcal{S}_\lambda \\
    U^{\otimes n} &\simeq \bigoplus_{\lambda \vdash_d n}  f_\lambda(U) \otimes \mathbb{I}_{\mathcal{S}_\lambda}\\
    \pi(\sigma) &\simeq \bigoplus_{\lambda \vdash_d n}  \mathbb{I}_{\mathcal{U}_\lambda} \otimes g_\lambda(\sigma),
\end{align}
where $\lambda \vdash_d n$ denotes a partition $(\lambda_1, \lambda_2, \cdots \lambda_d)$ satisfying
$\lambda_1+ \lambda_2+ \cdots \lambda_d=n$, $\lambda_1 \geq \lambda_2 \geq \cdots \geq \lambda_d\geq 0$, while $f_\lambda: U(d) \to \mathcal{L}(\mathcal{U}_\lambda)$, $g_\lambda: \mathfrak{S}_n \to \mathcal{L}(\mathcal{S}_\lambda)$ denote the irreducible representation of $U(d)$ and $\mathfrak{S}_n$ labeled by the partition $\lambda$, respectively. We use $\ell(\lambda)$ to denote the height of the Young diagram $\lambda$, the number of nonzero entries in the partition. We also define the dimensions $d_\lambda := \dim \mathcal{U}_\lambda, m_\lambda:= \dim \mathcal{S}_\lambda$ and employ the Gelfand-Tsetlin basis $\{|u\rangle\}_{u\in [d_\lambda]}$~\cite{goodman2009symmetry} as an orthonormal basis for $\mathcal{U}_\lambda$ and the Young-Yamanouchi basis $\{|i\rangle\}_{i\in [m_\lambda]}$~\cite{james2006representation} for an orthonormal basis for $\mathcal{S}_\lambda$. We call the basis $\{|\lambda, u, i \rangle\}_{\lambda \vdash_d n}$ the Schur basis. The unitary transformation taking the computational basis to the Schur basis $U_{\textrm{Sch}}^{(n,d)}$ is called the quantum Schur transform. The Young-Yamanouchi basis is associated to the standard Young tableau (SYT). The matrix unit, defined by 
\begin{align}
    E^\lambda_{ij}:= \mathbb{I}_{d_\lambda} \otimes |i\rangle \langle j|, 
\end{align}
enjoys the following convenient properties~\cite{9815215} 
\begin{align}\label{eq:YYformula}
\begin{dcases}
    E^{\alpha}_{ab} \otimes \mathbb{I}_d = \sum_{\mu \in \alpha + \Box} E^{\mu}_{a_\mu b_\mu}\\
    \Tr_{n+1} E_{ij}^\mu  = \delta_{\alpha \beta} \frac{d_\mu}{d_\alpha} E^{\alpha}_{i', j'}
\end{dcases}
\end{align}
where $\alpha+\Box$ is the set of Young diagrams obtained by adding a box to $\alpha$, $\alpha_\mu, b_\mu$ is the SYT obtained by adding the box $n+1$ to the SYT $a,b$, and $i',j'$ are SYT with frame $\alpha, \beta$ that can be obtained from SYT $i,j$ by removing the box $n+1$. In the second equation, the partial trace vanishes if the two tableaux have different shapes after removing $n+1$. 
\subsection{Mixed Schur-Weyl duality}
Mixed Schur-Weyl duality~\cite{koike1989decomposition,benkart1994tensor,grinko2025mixed} is a representation-theoretic machinery for handling the mixed tensor representation $U^{\otimes n}\otimes (U^*)^{\otimes m}$ of the unitary group $\mathrm{U}(d)$. To introduce this tool, we first review the walled-Brauer algebra $\mathcal{B}_{n,m}^\delta$. 

Let $n,m>0$ be integers and let $\delta\in \mathbb{C}$. Walled-Brauer algebra consists of complex combinations of walled-Brauer diagrams, which is a diagram of two rows with $n+m$ nodes separated by a vertical ``wall" that separates $n$ nodes and $m$ nodes. The nodes are paired together under the following restriction: if both nodes are in the same row, they must be on different sides of the wall, while if they are in different rows, they must be on the same side of the wall. In plain language, a walled-Brauer diagram is a SWAP diagram that is partially transposed on the last $m$ nodes (See FIG~\ref{fig:WBdiagram}). To multiply two walled-Brauer diagrams, one simply concatenates the diagrams vertically. Whenever a loop forms under the concatenation, we remove it and multiply the diagram by $\delta$. 
\begin{figure*}[h]
  \centering

  \caption{A walled-Brauer diagram $\sigma \in \mathcal{B}_{3,2}^\delta$, which is a ``partially transposed" SWAP diagram.}
  \label{fig:WBdiagram}
\end{figure*}

One can consider the following matrix representation of the walled-Brauer algebra: 
\begin{align}
    \pi_{n,m}^d(\sigma) (|i_1\rangle |i_2\rangle \cdots |i_{n+m}\rangle) = \sum_{j_1, \cdots  j_{n+m}=1}^d \sigma_{j_1, \cdots j_{n+m}}^{i_1, \cdots i_{n+m}} (|j_1\rangle |j_2\rangle \cdots |j_{n+m}\rangle), 
\end{align}
where $\sigma_{j_1, \cdots j_{n+m}}^{i_1, \cdots i_{n+m}} = \prod_{(t,b)\in \sigma} \delta_{i_t, j_b}$. This is a natural generalization of the unitary representation of symmetric group in Eq.~\eqref{eq:perm}. The algebra generated by this representation is called the partially transposed permutation matrix algebra, $\mathcal{A}_{n,m}^d$.

The mixed Schur-Weyl duality is the statement that the mixed tensor representation $U^{\otimes n}\otimes (U^*)^{\otimes m}$ and the partially transposed permutation matrix $\pi_{n,m}^d(\sigma)$ can be simultaneously block-diagonalized in the following way: 
\begin{align}
    (\mathbb{C}^d)^{\otimes n}\otimes (\bar{\mathbb{C}}^d)^{\otimes m} &\simeq \bigoplus_{\gamma:\mathrm{irrep}} \mathcal{U}_\gamma\otimes S_{\gamma},\\
    U^{\otimes n}\otimes (U^*)^{\otimes m} &= \bigoplus_{\gamma:\mathrm{irrep}} f_\gamma(U) \otimes \mathbb{I}_{S_\gamma}, \quad U \in \mathrm{U}(d),\\
    \pi_{n,m}^d(\sigma) &= \bigoplus_{\gamma:\mathrm{irrep}} \mathbb{I}_{\mathcal{U}_\gamma} \otimes g_\gamma(\sigma) ,\quad \sigma \in \mathcal{B}_{n,m}^d.
\end{align}
Here, the irreps $\gamma$ are labeled by a pair of Young diagrams, and $\mathcal{U}_\gamma, \mathcal{S}_\gamma$ are called the Weyl module and the Specht module, respectively. To obtain the concrete form of the irrep labels, one first constructs the \textit{Bratteli diagram} of the walled-Brauer algebra $\mathcal{B}_{n,m}^d$ according to the following rule~\cite{bulgakova2020fusion}:
\begin{itemize}
    \item Start from a pair of null diagrams $(\phi, \phi)$. 
    \item To the left of the wall (the first $n$ levels), add a single box to the left diagram. 
    \item To the right of the wall (the last $m$ levels), remove a single box from the left diagram, or add a single box to the right diagram. 
\end{itemize}
\begin{figure*}[t]
  \centering

  \caption{The Bratteli diagram for $\mathcal{A}_{3,1}^d$. The dashed line represents the ``wall". Before crossing the wall, a box is added to the left diagram. After crossing the wall, a box is either removed from the left diagram, or added to the right diagram. For $d=3$, the edge with the red shade is removed because $\ell(\lambda) + \ell(\mu) > d$.}
\end{figure*}
After this procedure, one removes the edges $(\lambda, \mu)$ from the Bratteli diagram if $\ell(\lambda) + \ell(\mu) > d$. This is the Bratteli diagram of the partially transposed permutation matrix algebra $\mathcal{A}_{n,m}^d$, and the resulting vertices on the final level represent the irreps $\gamma$ that appear in the mixed Schur-Weyl duality. We use the notation $\ell(\gamma):= \ell(\lambda) + \ell(\mu)$ for $\gamma=(\lambda, \mu)$. The basis of $S_\gamma$ can be identified with a path in the Bratteli diagram of $\mathcal{A}_{n,m}^d$. This construction includes the Young-Yamanouchi basis as a special case, $m=0$: A standard Young tableau (SYT) corresponds to a path in the Bratteli diagram with no ``walls". 

The basis $\{|u_\gamma\rangle |\gamma\rangle |s_\gamma\rangle\}$ is called the mixed Schur basis, and the unitary transformation taking the computational basis to the mixed Schur basis is called the mixed Schur transform~\cite{grinko2024efficientquantumcircuitsportbased, nguyen2023mixedschurtransformefficient, fei2023efficientquantumalgorithmportbased}, which we denote by $U_{\mathrm{mSch}}^{(n,m)}$. 

\subsection{Clebsch-Gordan transforms}
Let $\rho_\lambda, \rho_\mu$ be irreducible representations of the unitary group $\mathrm{U}(d)$, with $\lambda \vdash_d n, \mu \vdash_d m$, and let $N=n+m$. Although $\rho_\lambda, \rho_\mu$ are both irreducible, its tensor-product representation $\rho_\lambda \otimes \rho_\mu$ is generally reducible: 
\begin{align}\label{eq:CGdecomposition}
    \mathcal{U}_\lambda \otimes \mathcal{U}_\mu \simeq \bigoplus_{\nu \vdash_d{N}} \mathcal{U}_\nu \otimes \mathbb{C}^{c_{\lambda \mu}^\nu}, 
\end{align}
where $c_{\lambda \mu}^\nu$ is the Littlewood-Richardson coefficient. Generally, the Clebsch-Gordan transform is the basis transformation that establishes the above isomorphism. In this paper, we are specifically interested in the case where one of the irreps in Eq.~\eqref{eq:CGdecomposition} is the fundamental representation $\Box$: 
\begin{align}
    \mathcal{U}_\lambda \otimes \mathcal{U}_\Box \simeq \bigoplus_{\substack{\nu \vdash_d{N}\\
    \nu = \lambda + \Box}} \mathcal{U}_\nu. 
\end{align}
In this case, the decomposition is multiplicity-free due to the Pieri rule~\cite{macdonald1995symmetric}. We use $\mathrm{CG}$ to denote the Clebsch-Gordan transform, which is the basis transformation $|u_\lambda\rangle \otimes |u_\Box\rangle \to |\nu\rangle |u_\nu\rangle$~\cite{bacon2005quantumschurtransformi,harrow2005applications}. Similarly, the tensor product of Weyl modules in the mixed Schur-Weyl duality decomposes into irreducible representations. When one of the irreps is the anti-fundamental representation $\bar{\Box}$, 
\begin{align}
    \mathcal{U}_\gamma \otimes \mathcal{U}_{(\phi, \Box)} \simeq \bigoplus_{\substack{\nu \in \gamma-\Box\\
    \ell(\nu) \leq d}} \mathcal{U}_\nu. 
\end{align}
The dual Clebsch-Gordan transform is the basis transformation $|u_\gamma\rangle \otimes |u_{\bar{\Box}}\rangle \to |\nu\rangle |u_\nu\rangle$, which we denote by $\mathrm{dCG}$~\cite{grinko2024efficientquantumcircuitsportbased, nguyen2023mixedschurtransformefficient, fei2023efficientquantumalgorithmportbased}.

\subsection{Quadratic Casimir operator}
Let $G$ be a Lie group and let $\mathfrak{g}$ be its Lie algebra. Let $\rho: G \to \mathrm{GL}(W)$ be a representation of $G$ on a vector space $W$. The representation $\rho$ induces a Lie algebra representation $\mathrm{d}\rho: \mathfrak{g} \to \mathcal{L}(W)$ by differentiation at the identity: 
\begin{align}
    \mathrm{d}\rho(X) =  \frac{1}{i}\left.\dv{\theta} \rho(\mathrm{exp}(i\theta X))\right|_{\theta =0}. 
\end{align}
If $\{X_1, \ldots, X_{\dim \mathfrak{g}}\}$ is the basis of the Lie algebra, $\mathrm{d}\rho(X_1), \cdots \mathrm{d}\rho(X_{\dim \mathfrak{g}})$ are called the infinitesimal generators of the representation on $W$. This preserves the Lie brackets:
\begin{align}
    d\rho(i[X,Y]) = i[\mathrm{d}\rho(X), \mathrm{d}\rho(Y)]. 
\end{align}

\noindent \underline{Example 1: Anti-fundamental representation}\\
The anti-fundamental representation is given by 
\begin{align}
    \rho_{\mathrm{conj}}(U) = U^*. 
\end{align}
Let $\{T_a\}$ be the Hermitian traceless basis for the Lie algebra. Then, 
\begin{align*}
    \rho_{\mathrm{conj}}(U) = e^{-i\theta T_a^T}, 
\end{align*}
so the generators are $-T_a^T$. \\

\noindent \underline{Example 2: Adjoint representation}\\
The adjoint representation acts on traceless matrices by conjugation: 
\begin{align}
    \rho_{\mathrm{Adj}}(U)(X) = UXU^\dagger.  
\end{align}
Differentiating gives 
\begin{align}
     \frac{1}{i}\left.\dv{\theta} (e^{iT_a\theta}Xe^{-iT_a\theta})\right|_{\theta =0} = [T_a, X]. 
\end{align}
Thus, the generator corresponding to $T_a$ is given by $F_a(\cdot) := [T_a, \cdot]$. Thus, 
\begin{align}
    [F_a]_{cb} = \frac{1}{d} \Tr([T_a, T_b] T_c)= 2if_{abc}. 
\end{align}
Now, let $T_a$ be the basis of a Lie algebra and let $G_a$ be the corresponding generators in a representation $W$. The quadratic Casimir operator on $W$ is given by 
\begin{align}
    C = \sum_a G_a^2. 
\end{align}
This operator commutes with the generators: 
\begin{align}
    [C, G_b] = 0.  
\end{align}
Now, consider two representations $\rho_\lambda(U), \rho_\mu(U)$ and the tensor-product representation 
\begin{align}
    \rho_{\lambda \otimes \mu}(U) = \rho_\lambda(U) \otimes \rho_\mu(U). 
\end{align}
Let $G_a^{(\lambda)}, G_a^{(\mu)}$ denote the generators corresponding to the basis $T_a$ in the representation $\rho_\lambda, \rho_\mu$. Then, the generator corresponding to the basis $T_a$ in the representation $\lambda \otimes \mu$ is 
\begin{align}
    G_a^{\mathrm{tot}} = G_a^{(\lambda)} \otimes \mathbb{I} + \mathbb{I}\otimes G_a^{(\mu)}, 
\end{align}
and the total Casimir operator is 
\begin{align}
    C_{\mathrm{tot}} = \sum_a (G_a^{(\lambda)} \otimes \mathbb{I} + \mathbb{I}\otimes G_a^{(\mu)})^2 = C_\lambda \otimes \mathbb{I} + \mathbb{I}\otimes C_\mu + 2\sum_{a} G_a^{(\lambda)} \otimes G_a^{(\mu)}. 
\end{align}
If an irrep is represented by a Young diagram $\lambda=(\lambda_1, \lambda_2, \cdots \lambda_d)$ and $\sum_i \lambda_i = m$, one has~\cite{Piddock:2018xyi} 
\begin{align}\label{eq:Piddockequation}
    C(\lambda) = d^2m + d\sum_{i=1}^{d} \lambda_i(\lambda_i+1-2i)-m^2. 
\end{align}

\section{Existence of the leading-order coefficient}
\noindent Here we justify Definition 1 in the main text by showing that the limit indeed exists. We use an argument that is similar to Danskin's theorem~\cite{danskin1966, bertsekas2003convex} in convex optimization. 
\begin{lm}
The set of the Choi matrices of deterministic sequential superchannels is \textit{compact}. 
\end{lm}
\begin{proof}
Since Choi matrices of superchannels are Hermitian and thus can be considered as a real vector space, Heine-Borel theorem~\cite{rudin1976principles} implies that it suffices to show that the set is closed and bounded. The closedness follows because Choi matrices are positive semidefinite and constrained by partial trace. Boundedness follows because the trace is a constant. 
\end{proof}

\begin{lm}\label{lm:Danskin}
Let $\mathcal{K}_{n,d}$ be the set of Choi matrices of $n$-slot deterministic sequential superchannels on a $d$-dimensional system, and let $\Omega_{n,p}$ denote the performance operator for noisy unitary purification. We denote the fidelity achieved by a strategy $J$ by $h_{n,d}(p,J):=\Tr[\Omega_{n,p}^TJ]$. Then, 
\begin{align}
f_{n,d}(p) = \max_{J\in  \mathcal{K}_{n,d}} h_{n,d}(p,J). 
\end{align}
Let $\mathcal{M}_{n,d}$ be a set 
\begin{align}
    \mathcal{M}_{n,d} := \{ J \in \mathcal{K}_{n,d}| h_{n,d}(0,J) = f_{n,d}(0) = 1\}. 
\end{align}
The coefficient 
\begin{align}
    C_{n,d}:= \lim_{p\to 0} \frac{1-f_{n,d}(p)}{p}
\end{align}
exists, and its value is 
\begin{align}
    C_{n,d} = -\max_{J \in \mathcal{M}_{n,d}} \Tr(\dot{\Omega}_{n,0}^TJ). 
\end{align}
\end{lm}

\begin{proof}
We show the claim 
\begin{align}
    \left.\dv{p} \max_{\mathcal{J} \in \mathcal{K}_{n,d}} \Tr(\Omega_{n,p}^T \mathcal{J})\right|_{p=0} = \max_{\mathcal{J} \in \mathcal{M}_{n,d}} \partial_p h_{n,d}(0, \mathcal{J}). 
\end{align}
First, observe that $\Omega_{n,p}$ is a polynomial of $p$, so we can expand it as 
\begin{align}
    \Omega_{n,p} = \Omega_{n,0}+p\dot{\Omega}_{n,0}+p^2R_{n,d}(p). 
\end{align}
Thus, for the fidelity $h_{n,d}(p,J)$ achieved by a strategy $J$, 
\begin{align}
    h_{n,d}(p,J) = h_{n,d}(0,J) + p\Tr(\dot{\Omega}_{n,0}^TJ) + p^2\Tr(R_{n,d}(p)^TJ). 
\end{align}
For a sufficiently small $p$ in the interval $0\leq p \leq p_0$, one can make $\lVert R_{n,d}(p) \rVert_\infty$ finite. Using Hölder's inequality, we have 
\begin{align*}
    |\Tr(R_{n,d}(p)^TJ)| \leq \Tr|R_{n,d}(p)^TJ| \leq \lVert R_{n,d}(p)\rVert_\infty \lVert J \rVert_1
\end{align*}
so 
\begin{align}\label{eq:huniform}
    h_{n,d}(p,J) = h_{n,d}(0,J) + p\Tr(\dot{\Omega}_{n,0}^T J) + O_{n,d}(p^2). 
\end{align}
\noindent Here, note that $J$ can in principle depend on $p$. Next, let $J_\star \in \mathcal{M}_{n,d}$ maximize $\Tr(\dot{\Omega}_{n,0}^T J)$ over $J \in \mathcal{M}_{n,d}$. From Eq.~\eqref{eq:huniform}
\begin{align}
    h_{n,d}(p, \mathcal{J}_\star) = h_{n,d}(0, \mathcal{J}_\star) + p\Tr(\dot{\Omega}_{n,0}^T J_\star) + O_{n,d}(p^2). 
\end{align}
Since $f_{n,d}(p) \geq h_{n,d}(p,J_\star)$ and $f_{n,d}(0) = h_{n,d}(0,\mathcal{J}_\star)$, we have 
\begin{align}
    \liminf_{p\to 0} \frac{f_{n,d}(p)-f_{n,d}(0)}{p} \geq \liminf_{p\to 0} \frac{h_{n,d}(p, J_\star)-h_{n,d}(0, J_\star)}{p}  = \max_{J \in \mathcal{M}_{n,d}}\Tr(\dot{\Omega}_{n,0}^T J). 
\end{align}
Finally, for each $p>0$, choose the optimizer $J_p$. Also choose any operator $J_0 \in \mathcal{M}_{n,d}$. Then,
\begin{align}
    h_{n,d}(p, J_p) \geq h_{n,d}(p,J_0) \to f_{n,d}(0) \quad (p\to 0). 
\end{align}
Since $h_{n,d}(p,J_p)\to h_{n,d}(0, J_p)$ converges uniformly on $\mathcal{K}_{n,d}$, $h_{n,d}(0, J_p) \to f_{n,d}(0)$. Indeed, using 
\begin{align}
    \epsilon_p := \sup_{J \in \mathcal{K}_{n,d}}|h_{n,d}(p, J)-h_{n,d}(0, J)|, 
\end{align}
uniform convergence gives $h_{n,d}(0, J_p) \geq h_{n,d}(p, J_p) -\epsilon_p$ and $h_{n,d}(p,J_0) \geq h_{n,d}(0,J_0) -\epsilon_p =f_{n,d}(0)-\epsilon_p$. Combined with $h_{n,d}(p, J_p) \geq h_{n,d}(p, J_0)$, this yields $f_{n,d}(0) \geq h_{n,d}(0, J_p) \geq f_{n,d}(0)-2\epsilon_p$. Now, Lemma 1 tells us that $\mathcal{K}_{n,d}$ is compact, so any sequence $p_k\to  0$ has a subsequence such that $J_{p_k} \to\bar{J}$ and continuity gives $h_{n,d}(0, \bar{J}) = f_{n,d}(0)$. Therefore, every limiting optimizer satisfies $\bar{J} \in \mathcal{M}_{n,d}$. Now,
\begin{align}
    \frac{f_{n,d}(p) - f_{n,d}(0)}{p} &= \frac{h_{n,d}(p, J_p)-h_{n,d}(0,J_p)}{p}+\frac{h_{n,d}(0, J_p)-f_{n,d}(0)}{p}\nonumber\\
    & \leq \frac{h_{n,d}(p, J_p)-h_{n,d}(0,J_p)}{p} \nonumber\\
    &= \Tr(\dot{\Omega}_{n,0}^T J_p) + O_{n,d}(p)
\end{align}
so take any sequence $p_k$ such that its subsequence converges to $\bar{J}\in \mathcal{M}_{n,d}$. This yields 
\begin{align}
    \limsup_{p\to 0} \frac{f_{n,d}(p)-f_{n,d}(0)}{p} \leq \Tr(\dot{\Omega}_{n,0}^T \bar{J}) \leq \max_{J \in \mathcal{M}_{n,d}} \Tr(\dot{\Omega}_{n,0}^T J). 
\end{align}
\end{proof}

\begin{cor}\label{cor:noiseless}
The set $\mathcal{M}_{n,d}$ in Lemma~\ref{lm:Danskin} is characterized as the noiseless face $\mathcal{M}_{n,d} = \{\mathcal{J}_\Xi \in \mathcal{K}_{n,d}| \Xi(\mathcal{U}^{\otimes n}) = \mathcal{U}\}$. Thus, it is sufficient to optimize $h_{n,d}(p,J)$ over the noiseless face $\mathcal{M}_{n,d}$, instead of $\mathcal{K}_{n,d}$. 
\end{cor}
\begin{proof}
$f_{n,d}(0) = 1$. Thus, $\mathcal{J}_\Xi \in \mathcal{M}_{n,d} \implies \int \mathrm{d}U f_{\mathrm{Choi}}(\Xi(\mathcal{U}^{\otimes n}), \mathcal{U}) = 1$. This further implies $f_{\mathrm{Choi}}(\Xi(\mathcal{U}^{\otimes n}), \mathcal{U})=1$ for all $\mathcal{U}$, and therefore $\Xi(\mathcal{U}^{\otimes n}) = \mathcal{U}$. The converse, $\Xi(\mathcal{U}^{\otimes n}) = \mathcal{U} \implies J_\Xi \in \mathcal{M}_{n,d}$ is obvious. 
\end{proof}

\begin{cor}\label{cor:noiselessconjugate}
The first-order infidelity coefficient $C'_{n,d}$ for the noisy conjugation problem also exists for $n\geq d-1$. Furthermore, it suffices to optimize over the noiseless face 
$\{\mathcal{J}_\Xi \in \mathcal{K}_{n,d}|\Xi(\mathcal{U}^{\otimes n}) = \mathcal{U}^*\}$. 
\end{cor}
\begin{proof}
In the proof of Lemma~\ref{lm:Danskin} and Corollary~\ref{cor:noiseless}, we have only used the fact that $\Omega_{n,p}$ can be expanded as a polynomial in $p$, and that $f_{n,d}(0) =1$. These features survive in the noisy conjugation problem. That is to say, $\Omega'_{n,p}$ is a polynomial in $p$, and $g_{n,d}(0) =1$ for $n\geq d-1$~\cite{PhysRevResearch.1.013007}. 
\end{proof}

\section{Proof of Theorem 1}
