\section{Repeat-until-success protocol for nonlocal rotation gates}

The complete procedure for the Repeat-until-success (RUS) protocol to implement a nonlocal rotation gate $U_\theta =e^{-i\theta P_A\otimes P_B }$ is summarized in Alg.~\ref{alg:RUS_Appendix}. 

\begin{algorithm}[H]
\caption{RUS Protocol}
\label{alg:RUS_Appendix}
\begin{algorithmic}[1]

\Require Data state $\ket{\psi}_{AB}$; 
Pauli strings $P_A$ and $P_B$;
target angle $\theta$; 
desired success probability threshold $1-\delta\in(0,1)$
\Ensure $U_\theta\ket{\psi}$ upon success, with
$\Pr[\textsc{success}]\geqslant 1-\delta$

\State $K
\gets
\left\lceil
\log_2\!\left(\frac{1}{\delta}\right)
\right\rceil$

\For{$j=0,1,\ldots,K-1$}
    \State Set $\alpha_j \gets 2^j\theta$

    \State Alice and Bob prepare the entangled state $\ket{\phi_{\alpha_j}}\coloneqq\cos\alpha_j\ket{00}-\ii\sin\alpha_j\ket{11}$

    \State Alice and Bob apply controlled-$P_A$ and controlled-$P_B$,
    respectively, using $\ket{\phi_{\alpha_j}}$ as controls

    \State Measure $\ket{\phi_{\alpha_j}}$ in the Hadamard basis, obtaining $m_A, m_B\in\{0,1\}$

    \If{$m_A\oplus m_B=0$}
        \State \Return \textsc{success}
        \Comment{the evolution is $U_\theta$}
    \Else
        \State Continue to the next round
        \Comment{the accumulated evolution is
        $U_{-(2^{j+1}-1)\theta}$}
    \EndIf
\EndFor

\State \Return \textsc{failure}
\Comment{$U_{-(2^{K}-1)\theta}$,
with probability $2^{-K}\leqslant \delta$}

\end{algorithmic}
\end{algorithm}

\section {Finite-time RUS cost of Trotterization}
\label{app:longtime_rus_cost}

In this appendix we prove the linear-in-time cost bound used in
Theorem~\ref{thm:main}. The only estimate needed for the
Trotterization cost is an upper bound on the expected RUS cost of one weak
rotation. Recall that
\begin{equation}
    C_K(\theta)
    =
    \sum_{j=0}^{K-1}2^{-j}
    h_2\!\left(\sin^2(2^j\theta)\right),
\end{equation}
and define
$
    C_\infty(\theta)
    =
    \sum_{j=0}^{\infty}2^{-j}
    h_2\!\left(\sin^2(2^j\theta)\right).
$

\begin{lemma}[Lemma 1 in the main text]
\label{lem:Cinfty_upper}
For every $K\ge1$ and every $0<|\theta|\le1$,
\begin{equation}
    C_K(\theta)
    \le
    C_\infty(\theta)
    \le
    9|\theta|.
    \label{eq:CK_upper_9}
\end{equation}
\end{lemma}

\begin{proof}
Let $f(x)=h_2(\sin^2 x)$. We use the elementary
entropy bound
$
    h_2(p)
    \le
    p\log_2\frac{e}{p}
    $ with $ 0<p\le1,$
which follows from $-(1-p)\ln(1-p)\le p$. Hence, for $|x|\le1$,
\begin{equation}
    f(x)
    =
    h_2(\sin^2 x)
    \le
    x^2\log_2\frac{e}{x^2}.
    \label{eq:f_bound_simple}
\end{equation}

Choose $J\ge0$ such that
$ 2^J|\theta|\le1<2^{J+1}|\theta|,$
and write $b=2^J|\theta|$, so that $b\in(1/2,1]$. We split the infinite sum at
$j=J$. For $j\le J$, set $n=J-j$. Then $2^j|\theta|=b2^{-n}$, and
Eq.~\eqref{eq:f_bound_simple} gives
\begin{align}
    \sum_{j=0}^{J}2^{-j}f(2^j\theta)
    &\le
    |\theta|
    \sum_{n=0}^{J}
    b2^{-n}
    \left(
        \log_2\frac{e}{b^2}
        +2n
    \right)
    \nonumber \le
    |\theta| b
    \left[
        2\log_2\frac{e}{b^2}
        +4
    \right].
    \label{eq:small_angle_sum_bound}
\end{align}
Here we used $\sum_{n\ge0}2^{-n}=2$ and
$\sum_{n\ge0}n2^{-n}=2$. Define function
$
    \Phi(b)
    =
    b\left[
        2\log_2\frac{e}{b^2}
        +4
    \right]$ and one can verify that$ \Phi(b)$
is increasing on $b\in(1/2,1]$ since
$ \Phi'(b)
    >
    0.$
Therefore $\Phi(b)\le \Phi(1)=2\log_2 e+4$, and
\begin{equation}
    \sum_{j=0}^{J}2^{-j}f(2^j\theta)
    \le
    (2\log_2 e+4)|\theta|.
    \label{eq:small_angle_sum_final}
\end{equation}

For the tail $j>J$, we use $0\le f(x)\le1$:
\begin{equation}
    \sum_{j=J+1}^{\infty}2^{-j}f(2^j\theta)
    \le
    \sum_{j=J+1}^{\infty}2^{-j}
    =
    2^{-J}.
\end{equation}
Since $b=2^J|\theta|>1/2$, we have $2^{-J}=|\theta|/b<2|\theta|$. Combining this with
Eq.~\eqref{eq:small_angle_sum_final}, we obtain
\begin{equation}
    C_\infty(\theta)
    \le
    (2\log_2 e+6)|\theta|
    <
    9|\theta|.
\end{equation}
Finally, $C_K(\theta)\le C_\infty(\theta)$ because all summands are
nonnegative. This proves the claim.
\end{proof}

\subsection{Cost of Trotterization with the RUS protocol}
\label{subsec:rus_trotter_cost}

We now apply the single-gate RUS cost bound to a full product-formula
simulation.  We state the result for a general fixed-order product formula,
of which first-order Trotterization is a special case.

Let $q$denote the product-formula order and let $\tau=t/r$.  In one
Trotter segment, the nonlocal part of the formula can be written
schematically as a sequence of nonlocal Pauli rotations \cite{childsTheoryTrotterError2021}
\begin{equation}
    \exp[-i\theta_{\alpha,x}P_x],
    \qquad
    \theta_{\alpha,x}
    =
    a_{\alpha,x}J_x\tau
    =
    a_{\alpha,x}J_x\frac{t}{r},
    \label{eq:general_trotter_angle}
\end{equation}
where $\alpha=1,\ldots,\nu_q$ labels the nonlocal sweeps in one segment,
$\mathfrak{X}_\alpha$ is the set of nonlocal terms appearing
in sweep $\alpha$, and $a_{\alpha,x}$ are fixed formula-dependent
coefficients. For fixed product-formula order $q$, the number of sweeps
$\nu_q$ and the coefficients $a_{\alpha,x}$ are independent of $t$,
$r$, and the target precision.

For each interaction term $x$, define its total absolute coefficient weight
within one segment by
$
    A_{q,x}
    =
    \sum_{\alpha:\,x\in\mathfrak{X}_\alpha}
    |a_{\alpha,x}|.
$
We also write $A_q=\max_{x\in\mathfrak X}A_{q,x}$.  For first-order
Trotterization, $\nu_q=1$, $\mathfrak{X}_1=\mathfrak{X},$ $
a_{1,x}=1$, and hence $A_{q,x}=1$. For the standard, unmerged product-formula implementation considered here, each
nonlocal sublayer contains the same set of cross-cut interactions,
$\mathfrak X_\alpha=\mathfrak X$. Thus one segment contains
$\nu_q|\mathfrak X|$ nonlocal Pauli rotations. Possible cancellations,
commuting-group optimizations, or mergers between adjacent segments can only
reduce this number and do not affect the upper bounds derived below.

For one nonlocal rotation with angle $\theta_{\alpha,x}$, the expected cost
of a \(K\)-round RUS attempt is
\begin{equation}
    C_K(\theta_{\alpha,x})
    =
    \sum_{j=0}^{K-1}
    2^{-j}
    h_2\!\left(
        \sin^2(2^j\theta_{\alpha,x})
    \right).
    \label{eq:CK_general_angle}
\end{equation}
Therefore the total expected ebit cost over all $r$ segments is
\begin{equation}
    C_{\rm tot}^{(K)}
    =
    r
    \sum_{\alpha=1}^{\nu_q}
    \sum_{x\in\mathfrak{X}_\alpha}
    C_K(\theta_{\alpha,x}).
    \label{eq:Ctot_general_q_xxact}
\end{equation}

Each $K$-round RUS attempt fails only if all $K$ heralded signs are
unfavorable, which occurs with probability $2^{-K}$.  Indeed, for a
correction angle $\alpha'$, the measurement outcome $x\in\{0,1\}^{k_x}$
induces the Kraus operator
\begin{equation}
    M_x
    =
    2^{-k_x/2}
    \left(
        \cos\alpha'\,I
        -
        i(-1)^{|x|}\sin\alpha'\,P_x
    \right),
\end{equation}
and hence $M_x^\dagger M_x=2^{-k_x}I$.  Thus each parity occurs with
probability $1/2$, independently of the input state and independently of the
angle.  The conclusion does not require the correction angles
$2^j\theta_{\alpha,x}$ to remain small.

The total number of nonlocal RUS attempts in the circuit is
$
    M
    =
    r
    \sum_{\alpha=1}^{\nu_q}
    |\mathfrak{X}_\alpha|.
$
By the union bound,
$
    P_{\rm succ}
    \ge
    1-M2^{-K}.
$
Thus choosing
$
    K
    =
    \left\lceil
        \log_2\frac{M}{\delta}
    \right\rceil
$
ensures \(P_{\rm succ}\ge1-\delta\).

Assume now that all elementary Trotter angles satisfy
$ |\theta_{\alpha,x}|\le1$ 
for all  $\alpha,x.$
By Lemma~\ref{lem:Cinfty_upper},
$  C_K(\theta_{\alpha,x})
    \le
    9|\theta_{\alpha,x}|.$
Substituting Eq.~\eqref{eq:general_trotter_angle} into
Eq.~\eqref{eq:Ctot_general_q_xxact}, we obtain

\begin{align}
    C_{\rm tot}^{(K)}
    &\le
    9r
    \sum_{\alpha=1}^{\nu_q}
    \sum_{x\in\mathfrak{X}_\alpha}
    |a_{\alpha,x}J_x|\frac{t}{r}
    \nonumber=
    9t
    \sum_{x\in\mathfrak{X}}
    A_{q,x}|J_x|
    \nonumber\le
    9A_q t
    \sum_{x\in\mathfrak{X}}
    |J_x|.
    \label{eq:linear_time_general_q}
\end{align}
Therefore, for every fixed product-formula order $q$, the expected RUS cost
is linear in the simulated time and independent of the Trotter segment number
$r$, up to formula-dependent constants.
\begin{theorem}[Equivalent to Theorem 1 in the main text]
\label{thm:longtime_rus_cost}
Consider an $r$-segment product-formula simulation of fixed order $q $in
the bipartite setting.  Let the nonlocal rotations in one segment be
$
    \exp[-i\theta_{\alpha,x}P_x],
   $ with $
    \theta_{\alpha,x}
    =
    a_{\alpha,x}J_x t/r,
$
with \(\alpha=1,\ldots,\nu_q\) and \(x\in\mathfrak{X}_\alpha\).  Define
$
    M
    =
    r\sum_{\alpha=1}^{\nu_q}|\mathfrak{X}_\alpha|
$
and
$A_{q,x} =\sum_{\alpha:\,x\in\mathfrak{X}_\alpha}|a_{\alpha,x}|,
   $ $
    A_q=\max_{x\in\mathfrak{X}}A_{q,x}.
$
A $K$-round RUS implementation has expected ebit cost
\begin{equation}
    C_{\rm tot}^{(K)}
    =
    r
    \sum_{\alpha=1}^{\nu_q}
    \sum_{x\in\mathfrak{X}_\alpha}
    \sum_{j=0}^{K-1}
    2^{-j}
    h_2\!\left(
        \sin^2(2^j\theta_{\alpha,x})
    \right),
    \label{eq:theorem_general_cost}
\end{equation}
and success probability
$
    P_{\rm succ}\ge1-M2^{-K}.
$
Thus $K=\lceil\log_2(M/\delta)\rceil$ gives
$P_{\rm succ}\ge1-\delta$.  If all elementary angles satisfy
$|\theta_{\alpha,x}|\le1$, then
$
    C_{\rm tot}^{(K)}
    \le
    9A_qt
    \sum_{x\in\mathfrak{X}}|J_x|.
$
In particular, for fixed $q$,
\begin{equation}
    C_{\rm tot}^{(K)}
    =
    O\!\left(
        t\sum_{x\in\mathfrak{X}}|J_x|
    \right),
\end{equation}
where the hidden constant depends only on the chosen product formula.
\end{theorem}
A coarser but simpler bound is obtained from $A_{q,x}\le\nu_q$ whenever
$|a_{\alpha,x}|\le1$. In that case
$
    C_{\rm tot}^{(K)}
    \le
    9\nu_q t\sum_{x\in\mathfrak{X}}|J_x|.
$

\subsection{Protocol-specific lower bound for the RUS cost}
\label{app:rus_protocol_lower_bound}

In the main text we only use the upper bound
$C_K(\theta)\le 9|\theta|$ to prove the linear-in-time simulation cost.
For completeness, we record a matching lower bound for the proposed RUS
protocol when the cutoff reaches a constant-angle correction scale. This is a
protocol-specific statement and should not be interpreted as a lower bound on
all possible LOCC implementations.

\begin{lemma}[Protocol-specific saturation]
\label{lem:CK_protocol_lower}
Fix a constant $a\in(0,\pi/4)$. Define
$ m_a= \min_{x\in[a,2a]} h_2(\sin^2 x).
$
Then $m_a>0$. For every $0<|\theta|\le a$, if
$
    K\ge
    \left\lceil
    \log_2\frac{a}{|\theta|}
    \right\rceil+1,$
then
$
    C_K(\theta)
    \ge
    \frac{m_a}{2a}|\theta|.$
Together with $C_K(\theta)\le9|\theta|$, this implies
\begin{equation}
    C_K(\theta)=\Theta(|\theta|)
\end{equation}
for the proposed RUS protocol whenever the cutoff reaches the constant-angle
scale.
\end{lemma}

\begin{proof}
Let
$
    j_*=
    \left\lceil
    \log_2\frac{a}{|\theta|}
    \right\rceil.$
Then
$
    a\le 2^{j_*}|\theta|<2a.
$
Because $a\in(0,\pi/4)$, the interval $[a,2a]$ is contained in
$(0,\pi/2)$. Hence $h_2(\sin^2 x)$ is continuous and strictly positive on
$[a,2a]$, so $m_a>0$.

If $K\ge j_*+1$, the term $j=j_*$ is included in $C_K(\theta)$. Therefore
\begin{align}
    C_K(\theta)=
    \sum_{j=0}^{K-1}
    2^{-j}h_2\!\left(\sin^2(2^j\theta)\right)
    \ge
    2^{-j_*}h_2\!\left(\sin^2(2^{j_*}\theta)\right)
    \ge
    2^{-j_*}m_a.
\end{align}
Using $2^{j_*}|\theta|<2a$, we obtain
$
    2^{-j_*}>
    \frac{|\theta|}{2a}.
$
Thus
\begin{equation}
    C_K(\theta)
    \ge
    \frac{m_a}{2a}|\theta|.
\end{equation}
The upper bound
$C_K(\theta)\le9|\theta|$ then gives the claimed $\Theta(|\theta|)$ scaling
for this RUS protocol.
\end{proof}

\section{Finite-Accuracy Preparation of Weak Entangled Resources}
\label{app:finite_accuracy_dilution}

In the main text we quote the entanglement cost of a weak Bell resource
\begin{equation}
    \ket{\phi_\alpha}
    =
    \cos\alpha\ket{00}
    -
    i\sin\alpha\ket{11}
\end{equation}
as its entropy of entanglement,
$h_2(\sin^2\alpha)$. This is the asymptotic Bell-pair rate. In an actual
finite implementation, however, the resource states need not be prepared
perfectly. It is sufficient to prepare them to an accuracy comparable to the
error budget already assigned to the corresponding Trotter layer. This
appendix makes this statement precise.

For states, we use the trace distance
$   D(\rho,\sigma)
    =
    \frac12\|\rho-\sigma\|_1.$
For channels, we use the corresponding operational distance
\begin{equation}
    D_\diamond(\mathcal N,\mathcal M)
    =
    \frac12\|\mathcal N-\mathcal M\|_\diamond .
\end{equation}

\subsection{Stability of the RUS channel under resource errors}

The first observation is that approximate resource states translate directly
into approximate implemented channels.

\begin{lemma}[Resource error implies channel error]
\label{lem:resource_to_channel_xrror}
Let $\mathcal R$ be any fixed LOCC procedure that consumes an ideal resource
state $\omega$ and implements a channel $\mathcal N_\omega$ on the data.
If the resource state is replaced by $\widetilde\omega$, producing the
channel $\mathcal N_{\widetilde\omega}$, then
\begin{equation}
    D_\diamond(\mathcal N_\omega,\mathcal N_{\widetilde\omega})
    \le
    D(\omega,\widetilde\omega).
    \label{eq:resource_channel_stability}
\end{equation}
The same bound holds if $\mathcal R$ includes classical outcome registers,
success/failure flags, or adaptive measurements.
\end{lemma}

\begin{proof}
The LOCC procedure, including all measurements and classical registers, is a
CPTP map acting jointly on the input data and the resource state. For any
input state $\rho_{RA}$, including an arbitrary reference system $R$, the
two output states differ only through the replacement
\(\omega\mapsto\widetilde\omega\). Contractivity of trace distance under CPTP
maps gives
\begin{equation}
    D\!\left[
        \mathcal R(\rho_{RA}\otimes\omega),
        \mathcal R(\rho_{RA}\otimes\widetilde\omega)
    \right]
    \le
    D(\omega,\widetilde\omega).
\end{equation}
Taking the supremum over $\rho_{RA}$ gives
Eq.~\eqref{eq:resource_channel_stability}.
\end{proof}

Thus, if the approximate resource package used for one nonlocal RUS attempt
is within trace distance $\delta$ of the ideal resource package, then the
implemented RUS channel differs from the ideal-resource RUS channel by at
most $\delta$ in diamond distance.

\subsection{Finite weak entangled-pair preparation by finite-accuracy dilution}

Before stating the finite-copy preparation bound, we spell out the
Schmidt-basis structure of $n$ weak Bell resources.   Let
\begin{equation}
    \ket{\phi_\alpha}
    =
    \cos\alpha\ket{0}_A\ket{0}_B
    -
    i\sin\alpha\ket{1}_A\ket{1}_B .
\end{equation}
Consider $n$ copies of this state, with copy index
$\ell=1,\ldots,n$.  We write
$A^n=A_1\cdots A_n$ and $B^n=B_1\cdots B_n$.  For a bit string
$x=(x_1,\ldots,x_n)\in\{0,1\}^n$, define
\[
    \ket{x}_{A^n}
    =
    \ket{x_1}_{A_1}\cdots\ket{x_n}_{A_n},
    \qquad
    \ket{x}_{B^n}
    =
    \ket{x_1}_{B_1}\cdots\ket{x_n}_{B_n},
\]
and let $|x|=\sum_{\ell=1}^n x_\ell$ be its Hamming weight.  Expanding the
tensor product gives
\begin{equation}
    \ket{\phi_\alpha}^{\otimes n}
    =
    \sum_{x\in\{0,1\}^n}
    (\cos\alpha)^{n-|x|}
    (-i\sin\alpha)^{|x|}
    \ket{x}_{A^n}\ket{x}_{B^n}.
    \label{eq:n_copy_weak_bell_general}
\end{equation}
Equivalently, when $0\le\alpha\le\pi/2$, writing
$p=\sin^2\alpha$ and $1-p=\cos^2\alpha$, this becomes
\begin{equation}
    \ket{\phi_\alpha}^{\otimes n}
    =
    \sum_{x\in\{0,1\}^n}
    (1-p)^{(n-|x|)/2}
    (-i)^{|x|}
    p^{|x|/2}
    \ket{x}_{A^n}\ket{x}_{B^n}.
    \label{eq:n_copy_weak_bell_pq}
\end{equation}
For general $\alpha$, the same construction applies after replacing
$\cos\alpha$ and $\sin\alpha$ by their absolute values in the Schmidt
coefficients; the signs and phases are known and can be incorporated by local
phase conventions.

Consequently the Hamming weight $|x|$ is distributed
as a binomial random variable $X\sim{\rm Bin}(n,p)$, since there are
$\binom{n}{w}$ strings with $|x|=w$.  Therefore, the total Schmidt weight
of all strings with $|x|\le L$ is
\begin{equation}
    F_{n,L}(\alpha)
    =
    \sum_{|x|\le L}(1-p)^{n-|x|}p^{|x|}
    =
    \sum_{w=0}^{L}\binom{n}{w}(1-p)^{n-w}p^w
    =
    \Pr[{\rm Bin}(n,p)\le L].
    \label{eq:FnL_binomial}
\end{equation}
The discarded Schmidt weight is correspondingly
\begin{equation}
    1-F_{n,L}(\alpha)
    =
    \Pr[{\rm Bin}(n,p)>L].
    \label{eq:discarded_binomial_tail}
\end{equation}
The finite-copy dilution protocol below simply keeps the low-weight Schmidt
subspace $|x|\le L$ and discards the binomial tail.

\begin{proposition}[Truncated finite-copy dilution]
\label{thm:finite_dilution_truncation}
Fix integers $n\ge1$ and $0\le L\le n$. Define
$D_L
    =
    \sum_{w=0}^{L}\binom{n}{w},
$ $m_L
    =
    \left\lceil \log_2 D_L \right\rceil ,
$
and
$
    F_{n,L}(\alpha)
    =
    \sum_{w=0}^{L}
    \binom{n}{w}
    (1-p)^{n-w}p^w .
$
Using $m_L$ Bell pairs, Alice and Bob can prepare by LOCC a pure state $\ket{\Phi_{n,L}}$ satisfying
\begin{equation}
    D\!\left(
        \ket{\Phi_{n,L}}\bra{\Phi_{n,L}},
        \ket{\phi_\alpha}\bra{\phi_\alpha}^{\otimes n}
    \right)
    \le
    \sqrt{1-F_{n,L}(\alpha)} .
    \label{eq:block_trace_distance_bound}
\end{equation}
Equivalently, since
$
    1-F_{n,L}(\alpha)
    =
    \Pr[{\rm Bin}(n,\sin^2\alpha)>L],
$
block trace distance at most \(\delta\) is guaranteed whenever
$
    \Pr[{\rm Bin}(n,\sin^2\alpha)>L]\le \delta^2 .
$
\end{proposition}


\begin{proof}
Let $T_L=\{x\in\{0,1\}^n: |x|\le L\}$. The normalized truncated state is
\begin{equation}
    \ket{\Phi_{n,L}}
    =
    \frac{1}{\sqrt{F_{n,L}(\alpha)}}
    \sum_{x\in T_L}
    (1-p)^{(n-|x|)/2}
    (-i)^{|x|}
    p^{|x|/2}
    \ket{x}_A\ket{x}_B .
    \label{eq:truncated_state}
\end{equation}
Its Schmidt rank is at most $D_L=|T_L|$. Therefore it can be prepared from
$m_L=\lceil\log_2D_L\rceil$ Bell pairs: Alice and Bob first generate a
maximally entangled state of Schmidt rank at least $D_L$, and then convert
it by deterministic LOCC (with the majorization theorem) into the desired pure state with Schmidt rank
$D_L$ \cite{Nielsen_1999}.

The squared overlap with the ideal product state is exactly
\begin{equation}
    \left|
    \bra{\Phi_{n,L}}\phi_\alpha^{\otimes n}
    \right|^2
    =
    F_{n,L}(\alpha).
\end{equation}
For pure states, the trace distance is
\begin{equation}
    D(\ket{\psi}\bra{\psi},\ket{\varphi}\bra{\varphi})
    =
    \sqrt{1-|\langle {\psi|\varphi\rangle}|^2}.
\end{equation}
This gives Eq.~\eqref{eq:block_trace_distance_bound}.
\end{proof}

By monotonicity of trace distance under partial trace, the same block
guarantee implies that every individual copy marginal is also close to the
ideal weak Bell state:
\begin{equation}
    D(\rho_j,\ket{\phi_\alpha}\bra{\phi_\alpha})
    \le
    \sqrt{1-F_{n,L}(\alpha)} ,
    \label{eq:single_copy_marginal_bound}
\end{equation}
where $\rho_j$ is the marginal state of the $j$-th prepared copy.
However, the block guarantee in Eq.~\eqref{eq:block_trace_distance_bound} is
stronger and is the one used to control the error of a full circuit, since
the prepared copies may be correlated.

\subsection{Matching finite-resource preparation to the Trotter error budget}
\label{subsec:matching_resource_trotter_xrror}

We now explain how finite-accuracy preparation of the weak resource states is
incorporated into the full adaptive RUS Trotterization protocol. The important
point is that the error must be assigned to an entire $K$-round RUS attempt,
not only to the first weak resource. Indeed, if several unfavorable heralded
outcomes occur, the protocol uses resource states with doubled angles
$\theta,2\theta,\ldots,2^{K-1}\theta$. The preparation errors of all
resources that may be used in the adaptive correction sequence must therefore
be included in the error budget.

Let $g$ label a nonlocal RUS attempt in the product-formula circuit. For a
fixed-order product formula, one may take $g=(s,\alpha,x)$, where
$s=1,\ldots,r$ labels the Trotter segment, $\alpha$labels the nonlocal
sweep inside the segment, and $x\in\mathfrak{X}_\alpha$. The corresponding
initial rotation angle is denoted by $\theta_g$. A $K$-round ideal RUS
attempt may use the resource states with angles
$ \theta_g,\;2\theta_g,\;\ldots,\;2^{K-1}\theta_g .
$
For the purpose of error analysis, define the ideal resource package
\begin{equation}
    \Omega_{g,K}
    =
    \bigotimes_{j=0}^{K-1}
    \ket{\phi_{2^j\theta_g}}\bra{\phi_{2^j\theta_g}} .
    \label{eq:ideal_resource_package}
\end{equation}
This package notation is only an analytical device: operationally, the
resources can still be prepared and consumed on demand, and the entanglement
cost is counted only when a round is actually reached.

Suppose the actual prepared resource for round $j$ of attempt $g $is
$\widetilde \phi_{g,j}$, satisfying
\begin{equation}
    D\!\left(
        \widetilde \phi_{g,j},
        \ket{\phi_{2^j\theta_g}}\bra{\phi_{2^j\theta_g}}
    \right)
    \le
    \delta_{g,j},
    \label{eq:round_resource_xrror}
\end{equation}
where $D(\rho,\sigma)=\frac12\|\rho-\sigma\|_1$. Let
$
    \eta_g
    =
    \sum_{j=0}^{K-1}\delta_{g,j},
$ 
we have the following Lemma.

\begin{lemma}[Error of an approximate RUS resource package]
\label{lem:rus_package_xrror}
Let $\mathcal R_{g,K}$ be the ideal $K$-round RUS instrument for attempt
$g$, including the classical success/failure flag, and let
$\widetilde{\mathcal R}_{g,K}$ be the same adaptive LOCC protocol with the
approximate resources $\widetilde \phi_{g,j}$. Then
\begin{equation}
    D_\diamond(
        \mathcal R_{g,K},
        \widetilde{\mathcal R}_{g,K}
    )
    \le
    \eta_g ,
    \label{eq:rus_package_diamond_bound}
\end{equation}
where $D_\diamond(\mathcal N,\mathcal M)=\frac12\|\mathcal N-\mathcal M\|_\diamond$.
\end{lemma}

\begin{proof}
Consider first the mathematical protocol in which all $K$ resource registers
are supplied at the beginning, although the adaptive LOCC map only accesses
the $j$-th register if round $j$ is reached. This is equivalent to the
on-demand implementation for the input-output channel. The
entire adaptive RUS procedure is then a CPTP map acting on the data and the resource package. By contractivity of trace distance under CPTP maps, replacing the ideal package by the approximate package changes the resulting
instrument by at most the trace distance between the two packages.

It remains to bound the package distance. By a telescoping argument for
tensor products,
\begin{equation}
    D\!\left(
        \bigotimes_{j=0}^{K-1}\widetilde\phi_{g,j},
        \bigotimes_{j=0}^{K-1}
        \ket{\phi_{2^j\theta_g}}\bra{\phi_{2^j\theta_g}}
    \right)
    \le
    \sum_{j=0}^{K-1}\delta_{g,j}
    =
    \eta_g .
\end{equation}
Combining these two facts gives Eq.~\eqref{eq:rus_package_diamond_bound}.
\end{proof}

Let
$
    M
    =
    r\sum_{\alpha=1}^{\nu_q}|\mathfrak{X}_\alpha| = r \nu_q |\mathfrak{X}|
$
be the total number of nonlocal RUS attempts in the $r$-segment
fixed-order product formula. A hybrid argument over the $M$ attempts gives
a total resource-preparation error at most
$
    \sum_{g=1}^{M}\eta_g .
$
Therefore, if $\varepsilon_{\rm res}$ is the total error budget assigned to
finite resource preparation, it is sufficient to impose
\begin{equation}
    \eta_g
    =
    \sum_{j=0}^{K-1}\delta_{g,j}
    \le
    \frac{\varepsilon_{\rm res}}{M}
    \label{eq:eta_budget_per_attempt}
\end{equation}
for every RUS attempt $g$. A simple uniform allocation is
$
    \delta_{g,j}
    =
    \frac{\varepsilon_{\rm res}}{MK}
  $ for $
    j=0,\ldots,K-1.
$
More refined allocations are possible, but $\delta_{g,j}
    = \frac{\varepsilon_{\rm res}}{MK}$
is sufficient for a rigorous error bound.

We now relate this to the product-formula error. For a $q$-th order product
formula, write
\begin{equation}
    \epsilon_{\rm PF}(t,r)
    \le
    c_q\alpha_{q}\frac{t^{q+1}}{r^q},
    \label{eq:PF_xrror_budget}
\end{equation}
where $\alpha_{q}$ is the sum of
$(q+1)$-fold nested-commutator norms and $c_q$ is a formula-dependent
constant. One may choose the resource-preparation budget to be comparable to
the product-formula error, for example
\begin{equation}
    \varepsilon_{\rm res}
    =
    O(\epsilon_{\rm PF}(t,r)).
\end{equation}
Then $\delta_{g,j}
    = \frac{\varepsilon_{\rm res}}{MK}$ gives
\begin{equation}
    \delta_{g,j}
    =
    O\!\left(
        \frac{
            \alpha_{q}t^{q+1}
        }{
            r^{q}MK
        }
    \right)
    =
    O\!\left(
        \frac{
            \alpha_{q}t^{q+1}
        }{
            r^{q+1}K
            \nu_q|\mathfrak{X}|
        }
    \right).
    \label{eq:delta_round_trotter_scaling}
\end{equation}
Alternatively, if $r$ is chosen so that
$\epsilon_{\rm PF}(t,r)\le\epsilon/2$, one may take
$\varepsilon_{\rm res}\le\epsilon/2$, giving
\begin{equation}
    \delta_{g,j}
    =
    O\!\left(
        \frac{\epsilon}{MK}
    \right)
    =
    O\!\left(
        \frac{\epsilon}{
            rK \nu_q|\mathfrak{X}|
        }
    \right).
    \label{eq:delta_round_target_xrror}
\end{equation}

Finally, we translate each $\delta_{g,j}$into an explicit finite-Bell-pair
preparation cost. For round $j$ of attempt $g$, let
$
    \alpha_{g,j}=2^j\theta_g
$ and $
    p_{g,j}=\sin^2\alpha_{g,j}.
$
If \(n\) copies of the resource with angle \(\alpha_{g,j}\) are prepared as a
block, Proposition~\ref{thm:finite_dilution_truncation} shows that it is
sufficient to choose \(L_{g,j}\) such that
\begin{equation}
    \Pr\!\left[
        {\rm Bin}(n,p_{g,j})>L_{g,j}
    \right]
    \le
    \delta_{g,j}^2 .
    \label{eq:round_tail_condition}
\end{equation}
The corresponding integer number of Bell pairs is
\begin{equation}
    m_{g,j}
    =
    \left\lceil
        \log_2
        \sum_{w=0}^{L_{g,j}}
        \binom{n}{w}
    \right\rceil .
    \label{eq:round_integer_cost}
\end{equation}
Using the Bernstein-Chernoff bound, a sufficient explicit choice is
\begin{equation}
    L_{g,j}
    =
    \left\lceil
        np_{g,j}
        +
        \sqrt{
            2np_{g,j}
            \log\frac{1}{\delta_{g,j}^2}
        }
        +
        \frac{2}{3}
        \log\frac{1}{\delta_{g,j}^2}
    \right\rceil .
    \label{eq:Lgj_choice}
\end{equation}
Together with
$
    \sum_{w=0}^{L}\binom{n}{w}
    \le
    \left(\frac{en}{L}\right)^L
 $ and $
    1\le L\le n,$
this gives the finite-copy scaling
\begin{equation}
    m_{g,j}
    =
    O\!\left[
        L_{g,j}
        \log_2\!\left(
            \frac{en}{L_{g,j}}
        \right)
    \right].
    \label{eq:m_scaling_round}
\end{equation}
Thus finite resource synthesis only needs to meet the per-round accuracy specified in \eqref{eq:delta_round_target_xrror}. Exact preparation is unnecessary: the
finite-preparation error is absorbed into the total simulation error budget.
The possibility of repeated unfavorable RUS outcomes is already accounted for
by the package condition
$\sum_{j=0}^{K-1}\delta_{g,j}\le\varepsilon_{\rm res}/M$.

\end{widetext}

